/* TREIN-2 · RASCUNHOS DO TREINAMENTO
   ARQUIVO GERADO por scripts/treinamento/gerar-rascunhos.mjs. Não edite à mão.

   STATUS: APLICADA em 05/11/2026, com a aprovação APR-017, depois de TREIN_1_TREINAMENTO_POR_FUNCAO.sql.

   FAZ: carrega trilhas, módulos, aulas e questões na unidade seldeestrela. Tudo
   entra como RASCUNHO, invisível para a equipe até o dono aprovar. Só os módulos
   de pratos entram aprovados, porque mostram a ficha real, sem texto escrito.
   Rodar de novo não sobrescreve o que já foi editado.
   ROLLBACK: TREIN_1_ROLLBACK.sql. */

begin;

do $$
begin
  if to_regprocedure('public.trein_importar_pacote(text,jsonb)') is null then
    raise exception 'TREIN-2: aplique TREIN-1 antes. Nada foi alterado.';
  end if;
  if not exists (select 1 from public.unidades where id = 'seldeestrela') then
    raise exception 'TREIN-2: unidade seldeestrela não encontrada. Nada foi alterado.';
  end if;
end $$;

select public.trein_importar_pacote('seldeestrela', $trein${"modulos":[{"chave":"g-casa","area":"geral","ordem":10,"titulo":"Bem-vindo à casa","descricao":"Quem somos, como é o seu primeiro dia e como usar o Héfisto.","tipo":"aulas","aulas":[{"chave":"g-casa-1","titulo":"Nossa casa","duracao_minutos":5,"conteudo":"[PREENCHER: conte a história do restaurante, o que a casa serve e por que ela existe.]\n\n[PREENCHER: escreva o que nunca pode faltar no atendimento e na comida da casa.]\n\n[PREENCHER: dias e horários de funcionamento, e quem são os líderes de cada área.]\n\nQuando tiver dúvida sobre o jeito da casa, pergunte ao seu líder. Perguntar nunca é erro. Errado é adivinhar quando o cliente ou a segurança dependem da resposta.","questoes":[{"tipo":"prova","enunciado":"Você não sabe como a casa faz uma coisa. O que fazer?","opcoes":["Fazer do seu jeito","Perguntar ao líder","Esperar alguém perceber"],"correta":1,"explicacao":"Perguntar evita o erro. Ninguém espera que você saiba tudo no começo.","chave":"g-casa-1-q1","ordem":1}],"fontes":""},{"chave":"g-casa-2","titulo":"Seu primeiro dia","duracao_minutos":5,"conteudo":"Chegue antes do horário, com tempo para se trocar e estar pronto na hora de começar.\n\nAntes de começar:\n- bata o ponto no Héfisto;\n- vista o uniforme limpo e completo;\n- procure o seu líder e diga que chegou.\n\nNos primeiros dias, sua função é observar, perguntar e repetir. Anote o que aprender. Se não entendeu, peça para mostrarem de novo.\n\nSe for faltar ou atrasar, avise o líder o quanto antes. Quem avisa dá tempo de reorganizar a equipe.","questoes":[{"tipo":"prova","enunciado":"Qual é a primeira coisa a fazer ao chegar?","opcoes":["Ir direto para a sua área","Bater o ponto e se preparar","Tomar café antes de tudo"],"correta":1,"explicacao":"O ponto registra sua chegada. Depois vêm uniforme e apresentação ao líder.","chave":"g-casa-2-q1","ordem":1},{"tipo":"situacao","enunciado":"O ônibus quebrou e você vai chegar 40 minutos atrasado.","opcoes":["Chegar e explicar depois","Avisar o líder agora","Faltar para não passar vergonha"],"correta":1,"explicacao":"Avisar agora dá tempo para o líder reorganizar a equipe.","chave":"g-casa-2-q2","ordem":2}],"fontes":""},{"chave":"g-casa-3","titulo":"O Héfisto no seu dia","duracao_minutos":5,"conteudo":"O Héfisto é o sistema do restaurante. Entre sempre com a sua conta e nunca use a de outra pessoa: tudo que você registra fica com o seu nome.\n\nCom ele você pode, conforme a sua função:\n- bater o ponto;\n- fazer este treinamento;\n- consultar fichas técnicas;\n- lançar entrada e retirada no estoque;\n- imprimir etiquetas;\n- preencher checklists.\n\nSe uma tela não abrir, sua conta talvez não tenha essa permissão. Fale com o líder. Não peça a senha de um colega.","questoes":[{"tipo":"prova","enunciado":"Um colega oferece a senha dele para você usar. O que fazer?","opcoes":["Usar só desta vez","Anotar para depois","Recusar e falar com o líder"],"correta":2,"explicacao":"Cada registro fica no nome de quem entrou. A sua conta é só sua.","chave":"g-casa-3-q1","ordem":1}],"fontes":""}]},{"chave":"g-comportamento","area":"geral","ordem":20,"titulo":"Postura e convivência","descricao":"Como trabalhamos juntos, em qualquer área.","tipo":"aulas","aulas":[{"chave":"g-comp-1","titulo":"Trabalho em equipe","duracao_minutos":5,"conteudo":"Restaurante funciona em cadeia: quando uma pessoa falha, o cliente sente lá na frente.\n\nNo dia a dia:\n- fale com clareza e confirme o que entendeu;\n- ofereça ajuda quando terminar a sua parte;\n- avise antes de faltar um item, não depois;\n- resolva o problema primeiro e procure o motivo depois;\n- leve desentendimentos ao líder, nunca para a frente do cliente.\n\nRespeito é regra: nada de apelido ofensivo, grito, piada sobre o corpo, cor, origem, religião ou orientação de alguém. Assédio de qualquer tipo deve ser levado ao líder ou ao dono.","questoes":[{"tipo":"prova","enunciado":"Você percebeu que um ingrediente vai acabar durante o serviço. Quando avisar?","opcoes":["Agora, antes de faltar","Quando acabar","No fim do turno"],"correta":0,"explicacao":"Avisar antes dá tempo de buscar, trocar ou combinar com o salão.","chave":"g-comp-1-q1","ordem":1},{"tipo":"situacao","enunciado":"Um colega fez uma piada ofensiva sobre outra pessoa da equipe.","opcoes":["Rir para não criar clima","Não participar e avisar o líder","Responder com outra piada"],"correta":1,"explicacao":"Respeito é regra da casa. O líder precisa saber para resolver.","chave":"g-comp-1-q2","ordem":2}],"fontes":""},{"chave":"g-comp-2","titulo":"Celular, aparência e horários","duracao_minutos":4,"conteudo":"Durante o trabalho, o celular fica guardado. Use-o na pausa, fora da área de trabalho.\n\nAparência faz parte do serviço: uniforme limpo, cabelo preso, higiene em dia.\n\nRespeite os horários de intervalo. Pausa combinada é direito seu e faz diferença para a equipe saber quando contar com você.\n\nNão comente problemas da casa, de clientes ou de colegas nas redes sociais.","questoes":[{"tipo":"prova","enunciado":"Onde usar o celular?","opcoes":["Na bancada, com a tela virada","Na pausa, fora da área de trabalho","No banheiro do cliente"],"correta":1,"explicacao":"Celular tira a atenção e leva sujeira para perto da comida.","chave":"g-comp-2-q1","ordem":1},{"tipo":"situacao","enunciado":"Um cliente famoso entrou na casa e um colega quer postar uma foto dele.","opcoes":["Postar só nos stories","Fotografar de longe","Não postar e respeitar a privacidade"],"correta":2,"explicacao":"O cliente veio comer em paz. A privacidade dele vem primeiro.","chave":"g-comp-2-q2","ordem":2}],"fontes":""}]},{"chave":"g-higiene","area":"geral","ordem":30,"titulo":"Higiene e segurança dos alimentos","descricao":"As regras que protegem o cliente, a equipe e a casa. Vale para todas as áreas.","tipo":"aulas","aulas":[{"chave":"g-hig-1","titulo":"Sua higiene pessoal","duracao_minutos":6,"conteudo":"Quem toca em alimento segue estas regras:\n- cabelo preso e coberto com touca ou rede;\n- sem barba;\n- unhas curtas, sem esmalte ou base;\n- sem anel, brinco, relógio, pulseira e maquiagem durante o preparo;\n- uniforme limpo e compatível com a função.\n\nLave bem as mãos:\n- ao chegar ao trabalho;\n- antes e depois de mexer com alimento;\n- depois de qualquer interrupção;\n- depois de tocar em lixo, dinheiro, celular ou outro material sujo;\n- depois de usar o banheiro.\n\nPerto do alimento, não fume, não coma, não cante, não assobie, não fale sem necessidade, não tussa nem espirre sobre a comida e não mexa em dinheiro.\n\nSe estiver doente, com diarreia, vômito, ferida ou corte, avise o líder antes de começar. Quem tem problema de saúde que possa contaminar o alimento sai do preparo até melhorar.","questoes":[{"tipo":"prova","enunciado":"Quando lavar as mãos?","opcoes":["Só ao chegar e ao sair","Ao chegar, antes e depois de mexer com alimento, depois de interrupções e do banheiro","Só quando estiverem visivelmente sujas"],"correta":1,"explicacao":"Mão limpa não é só a que parece limpa. A regra vale para cada um desses momentos.","chave":"g-hig-1-q1","ordem":1},{"tipo":"prova","enunciado":"O que pode ser usado por quem prepara alimento?","opcoes":["Touca e unhas curtas sem esmalte","Aliança lisa","Relógio com pulseira de silicone"],"correta":0,"explicacao":"Adornos saem durante o preparo, inclusive aliança e relógio.","chave":"g-hig-1-q2","ordem":2},{"tipo":"situacao","enunciado":"Você acordou com diarreia, mas está escalado para a cozinha.","opcoes":["Ir e não contar a ninguém","Tomar remédio e seguir normalmente","Avisar o líder antes de começar"],"correta":2,"explicacao":"Sintoma assim pode contaminar a comida. O líder decide como fica o seu turno.","chave":"g-hig-1-q3","ordem":3}],"fontes":"Anvisa, RDC 216/2004 (Boas Práticas para Serviços de Alimentação). Confira também as regras da vigilância sanitária da sua cidade."},{"chave":"g-hig-2","titulo":"Temperaturas que protegem","duracao_minutos":7,"conteudo":"Bactéria cresce no calor morno. Decore estes números da regra sanitária:\n\n- Cozinhar: todas as partes do alimento chegam a 70 °C ou mais.\n- Óleo de fritura: no máximo 180 °C. Troque quando mudar o cheiro ou o sabor, ou quando formar muita espuma ou fumaça.\n- Manter quente: acima de 60 °C, por no máximo 6 horas.\n- Resfriar comida pronta: de 60 °C até 10 °C em no máximo 2 horas.\n- Guardar na geladeira: abaixo de 5 °C. Comida pronta a 4 °C ou menos dura no máximo 5 dias.\n- Congelar: a -18 °C ou menos.\n- Descongelar: na geladeira, abaixo de 5 °C. Nunca em cima da bancada.\n- Alimento descongelado e não usado fica na geladeira e não volta ao freezer.\n\nPerecível só fica fora da geladeira o tempo mínimo do preparo. Se o prazo da casa for menor que o da regra, vale o da casa.","questoes":[{"tipo":"prova","enunciado":"Até que temperatura o alimento precisa chegar na cocção?","opcoes":["50 °C","60 °C","70 °C em todas as partes"],"correta":2,"explicacao":"70 °C em todas as partes, inclusive no meio da peça.","chave":"g-hig-2-q1","ordem":1},{"tipo":"prova","enunciado":"Como descongelar uma carne?","opcoes":["Na bancada, desde cedo","Na geladeira, abaixo de 5 °C","De molho em água morna"],"correta":1,"explicacao":"O descongelamento é feito sob refrigeração.","chave":"g-hig-2-q2","ordem":2},{"tipo":"prova","enunciado":"Por quanto tempo a comida pode ficar quente acima de 60 °C?","opcoes":["No máximo 6 horas","O dia inteiro","No máximo 12 horas"],"correta":0,"explicacao":"Depois de 6 horas, a regra não permite manter o alimento exposto.","chave":"g-hig-2-q3","ordem":3},{"tipo":"prova","enunciado":"Em quanto tempo a comida pronta deve ir de 60 °C a 10 °C?","opcoes":["Em até 8 horas","Em até 2 horas","Não há limite se estiver tampada"],"correta":1,"explicacao":"Quanto mais rápido passar pela faixa morna, mais seguro.","chave":"g-hig-2-q4","ordem":4},{"tipo":"situacao","enunciado":"Sobrou carne descongelada e não vai ser usada hoje.","opcoes":["Devolver ao freezer","Deixar na bancada até amanhã","Manter na geladeira, identificada, sem recongelar"],"correta":2,"explicacao":"Descongelado não volta ao freezer.","chave":"g-hig-2-q5","ordem":5}],"fontes":"Anvisa, RDC 216/2004 (Boas Práticas para Serviços de Alimentação). Confira também as regras da vigilância sanitária da sua cidade."},{"chave":"g-hig-3","titulo":"Contaminação cruzada e alérgenos","duracao_minutos":6,"conteudo":"Contaminação cruzada é levar sujeira ou bactéria de um lugar para outro, como de um alimento cru para um pronto.\n\nPara evitar:\n- separe cru de pronto na bancada e na geladeira;\n- troque ou higienize tábua, faca e utensílio entre um alimento e outro;\n- lave as mãos ao trocar de tarefa;\n- deixe o pronto sempre protegido.\n\nAlergia pode matar. Um traço de camarão, leite, amendoim ou glúten basta para causar reação grave. Quando houver pedido de cliente com alergia:\n- confirme o ingrediente na ficha;\n- avise o líder;\n- use utensílio e superfície limpos;\n- se não houver certeza, diga que não há certeza. Nunca chute.\n\nAlimento cru consumido sem cozimento, como salada e fruta, precisa ser higienizado com produto regularizado, seguindo a instrução dele.","questoes":[{"tipo":"prova","enunciado":"O que é contaminação cruzada?","opcoes":["Levar contaminação de um alimento ou superfície para outro","Misturar dois temperos","Cozinhar duas coisas juntas"],"correta":0,"explicacao":"A tábua da carne crua usada na salada é o exemplo clássico.","chave":"g-hig-3-q1","ordem":1},{"tipo":"situacao","enunciado":"Um cliente com alergia a camarão pede um prato. A panela acabou de ser usada com camarão.","opcoes":["Usar a mesma panela, passando um pano","Usar panela e utensílios limpos e avisar o líder","Retirar o camarão do prato pronto"],"correta":1,"explicacao":"Traços bastam para causar reação. Comece limpo.","chave":"g-hig-3-q2","ordem":2},{"tipo":"situacao","enunciado":"Perguntam se um prato tem amendoim e você não sabe.","opcoes":["Dizer que não tem","Dizer que acha que não tem","Dizer que vai confirmar e checar a ficha"],"correta":2,"explicacao":"Nunca chute sobre alergia.","chave":"g-hig-3-q3","ordem":3}],"fontes":"Anvisa, RDC 216/2004 (Boas Práticas para Serviços de Alimentação). Confira também as regras da vigilância sanitária da sua cidade."},{"chave":"g-hig-4","titulo":"Limpeza, lixo e identificação","duracao_minutos":5,"conteudo":"Limpeza faz parte do preparo. Limpe enquanto trabalha.\n\nLixo:\n- recipientes identificados, íntegros e fáceis de lavar;\n- nas áreas de preparo e estoque, tampa que abre sem usar a mão;\n- retire com frequência e leve para o local fechado, longe do preparo.\n\nIdentificação:\nTodo alimento preparado que vai para geladeira ou freezer leva etiqueta com nome, data de preparo e validade. Produto aberto ou fracionado leva nome, data do fracionamento e nova validade.\n\nNo estoque, respeite a validade: o que vence primeiro sai primeiro. Produto vencido não fica junto dos demais: separe, identifique e avise o líder.\n\nUse as etiquetas do Héfisto. Pote sem etiqueta é pote sem história.","questoes":[{"tipo":"prova","enunciado":"O que a etiqueta precisa ter, no mínimo?","opcoes":["Nome do produto, data de preparo e validade","Só o nome do produto","Nome de quem preparou"],"correta":0,"explicacao":"Esses três dados são o mínimo.","chave":"g-hig-4-q1","ordem":1},{"tipo":"situacao","enunciado":"Você encontra um pote na geladeira sem etiqueta.","opcoes":["Colocar uma etiqueta com a data de hoje","Usar e não comentar","Separar e chamar o líder"],"correta":2,"explicacao":"Sem saber quando foi feito, ninguém pode garantir a validade.","chave":"g-hig-4-q2","ordem":2},{"tipo":"prova","enunciado":"Em que ordem usar os produtos?","opcoes":["O mais novo primeiro","O que vence primeiro sai primeiro","O que estiver mais à mão"],"correta":1,"explicacao":"Assim nada vence esquecido no fundo.","chave":"g-hig-4-q3","ordem":3}],"fontes":"Anvisa, RDC 216/2004 (Boas Práticas para Serviços de Alimentação). Confira também as regras da vigilância sanitária da sua cidade."}]},{"chave":"g-seguranca","area":"geral","ordem":40,"titulo":"Segurança e emergências","descricao":"Como evitar acidentes e o que fazer quando eles acontecem.","tipo":"aulas","aulas":[{"chave":"g-seg-1","titulo":"Prevenir acidentes","duracao_minutos":5,"conteudo":"Os acidentes mais comuns em restaurante são corte, queimadura, queda e fogo.\n\n- Piso molhado: seque na hora ou sinalize.\n- Facas: use a faca certa e afiada, nunca a deixe dentro da pia, e não tente pegar uma faca que está caindo.\n- Panela quente: use pano seco e avise \"quente, passando\".\n- Atrás de alguém: avise \"atrás\".\n- Equipamento: só use depois de aprender. Desligue antes de limpar.\n- Sapato: fechado e antiderrapante.","questoes":[{"tipo":"prova","enunciado":"Uma faca está caindo da bancada. O que fazer?","opcoes":["Tentar segurar","Deixar cair e se afastar","Chutar para o lado"],"correta":1,"explicacao":"Tentar segurar uma faca caindo causa cortes graves.","chave":"g-seg-1-q1","ordem":1},{"tipo":"prova","enunciado":"Antes de limpar um equipamento elétrico:","opcoes":["Desligue-o da energia","Reduza a velocidade","Peça para alguém segurar"],"correta":0,"explicacao":"Equipamento ligado é risco de corte e choque.","chave":"g-seg-1-q2","ordem":2}],"fontes":""},{"chave":"g-seg-2","titulo":"Quando algo dá errado","duracao_minutos":6,"conteudo":"Corte: pare, lave, comprima com pano limpo e chame o líder. Se o corte for fundo ou não parar de sangrar, chame ajuda médica. Alimento que recebeu sangue é descartado.\n\nQueimadura: coloque em água corrente fria. Não use gelo, pasta de dente, manteiga ou pomada caseira. Não estoure bolhas. Avise o líder.\n\nFogo em panela com óleo: desligue o fogo se for seguro e abafe com a tampa. Nunca jogue água.\n\nCheiro de gás: não acenda nada, não mexa em interruptor, feche o registro se souber onde fica, abra portas e janelas, tire as pessoas do local e avise o líder.\n\nEmergência:\n- SAMU: 192;\n- Bombeiros: 193.\n\n[PREENCHER: onde ficam o extintor, o registro de gás, a caixa de primeiros socorros e a saída de emergência.]","questoes":[{"tipo":"prova","enunciado":"Fogo no óleo da panela. O que fazer?","opcoes":["Jogar água","Abafar com a tampa e desligar o fogo, se for seguro","Levar a panela para a pia"],"correta":1,"explicacao":"Água em óleo quente espalha o fogo.","chave":"g-seg-2-q1","ordem":1},{"tipo":"prova","enunciado":"Qual é o primeiro cuidado em uma queimadura?","opcoes":["Passar manteiga","Colocar pasta de dente","Colocar em água corrente fria"],"correta":2,"explicacao":"Água corrente fria. Nada de receita caseira.","chave":"g-seg-2-q2","ordem":2},{"tipo":"situacao","enunciado":"Você sente forte cheiro de gás ao abrir a cozinha.","opcoes":["Acender a luz para procurar o vazamento","Não acender nada, ventilar, tirar as pessoas e avisar","Ligar o exaustor"],"correta":1,"explicacao":"Qualquer faísca, até de interruptor, é perigosa.","chave":"g-seg-2-q3","ordem":3},{"tipo":"situacao","enunciado":"Um colega se cortou e sangrou em cima de uma preparação.","opcoes":["Descartar o alimento e cuidar do colega","Tirar só a parte de cima","Servir, pois vai ao fogo depois"],"correta":0,"explicacao":"Alimento com sangue não pode ser aproveitado.","chave":"g-seg-2-q4","ordem":4}],"fontes":""}]},{"chave":"c-conhecer","area":"cozinha","ordem":110,"titulo":"Conhecendo a cozinha","descricao":"A área, as praças, os equipamentos e a rotina.","tipo":"aulas","aulas":[{"chave":"c-con-1","titulo":"A cozinha e as praças","duracao_minutos":6,"conteudo":"Seu líder vai caminhar com você por toda a cozinha. Olhe, pergunte e anote.\n\nConheça:\n- onde o alimento entra e onde fica guardado;\n- onde é o pré-preparo, onde é o fogão e onde sai o prato;\n- onde ficam utensílios, panelas e produtos de limpeza;\n- quem responde por cada praça.\n\nUma praça é um posto de trabalho: fogão, fritura, frios, finalização. Cada uma tem o que precisa à mão. Manter a sua praça arrumada é parte do trabalho.\n\n[PREENCHER: nomes das praças da casa e quem é o responsável por cada uma.]","questoes":[{"tipo":"prova","enunciado":"O que é uma praça?","opcoes":["O salão","Um posto de trabalho da cozinha","A área do lixo"],"correta":1,"explicacao":"Cada praça concentra o que é preciso para aquele preparo.","chave":"c-con-1-q1","ordem":1}],"fontes":""},{"chave":"c-con-2","titulo":"Equipamentos","duracao_minutos":5,"conteudo":"Antes de usar qualquer equipamento, peça para alguém ensinar. Consulte também os Guias de uso no Héfisto.\n\nRegras:\n- leia a temperatura da geladeira e do freezer nos Controles;\n- não sobrecarregue equipamentos;\n- desligue da energia antes de limpar;\n- não deixe faca dentro de pia com água;\n- avise qualquer defeito na hora.\n\nEquipamento quebrado sem aviso vira problema no meio do serviço.","questoes":[{"tipo":"prova","enunciado":"A geladeira marca temperatura acima do normal. O que fazer?","opcoes":["Avisar o líder e registrar agora","Esperar o próximo turno","Colocar menos comida e não falar nada"],"correta":0,"explicacao":"Alimento perecível fora da temperatura corre risco. Avise na hora.","chave":"c-con-2-q1","ordem":1}],"fontes":""},{"chave":"c-con-3","titulo":"Abertura e fechamento","duracao_minutos":5,"conteudo":"A cozinha tem checklists de abertura e fechamento no Héfisto. Eles não são burocracia: garantem que nada foi esquecido.\n\nNa abertura, confira temperaturas, limpeza, gás, mise en place e validade.\n\nNo fechamento, guarde tudo identificado, limpe a praça, retire o lixo, desligue o que deve ser desligado e confira gás e geladeiras.\n\nMarque apenas o que você fez de verdade. Marcar sem fazer é pior do que não marcar, porque o próximo turno confia nisso.","questoes":[{"tipo":"prova","enunciado":"Faltou um item do checklist e o turno acabou. O que fazer?","opcoes":["Marcar assim mesmo","Deixar em branco e avisar o líder","Apagar o checklist"],"correta":1,"explicacao":"O checklist precisa dizer a verdade. Avise o que ficou pendente.","chave":"c-con-3-q1","ordem":1},{"tipo":"situacao","enunciado":"Seu colega pede para você marcar o checklist dele.","opcoes":["Marcar para ajudar","Não marcar: cada um registra o que fez","Marcar só os itens fáceis"],"correta":1,"explicacao":"O registro fica no seu nome, e você não viu aquilo ser feito.","chave":"c-con-3-q2","ordem":2}],"fontes":""}]},{"chave":"c-preparo","area":"cozinha","ordem":120,"titulo":"Pré-preparo e organização","descricao":"O que acontece antes do pedido chegar.","tipo":"aulas","aulas":[{"chave":"c-pre-1","titulo":"Mise en place","duracao_minutos":5,"conteudo":"Mise en place é deixar tudo pronto antes do serviço: cortado, porcionado, identificado e no lugar.\n\nBoa praça tem:\n- o que você vai usar à mão;\n- quantidade certa para o movimento do dia;\n- utensílios limpos;\n- bancada livre para trabalhar.\n\nVeja a Produção do dia e o Memorando de amanhã no Héfisto para saber o que preparar.","questoes":[{"tipo":"prova","enunciado":"O que é mise en place?","opcoes":["A limpeza final","Deixar tudo pronto antes do serviço","O prato do dia"],"correta":1,"explicacao":"Sem mise en place, o serviço trava.","chave":"c-pre-1-q1","ordem":1},{"tipo":"situacao","enunciado":"Você vê na Produção do dia um item que não sabe fazer.","opcoes":["Tentar adivinhar","Pular o item","Pedir ajuda e consultar a ficha"],"correta":2,"explicacao":"A ficha e o líder garantem o padrão.","chave":"c-pre-1-q2","ordem":2}],"fontes":""},{"chave":"c-pre-2","titulo":"Ficha técnica: a receita da casa","duracao_minutos":6,"conteudo":"A ficha técnica é a receita oficial. Ela define ingredientes, quantidades, rendimento e preparo. O cliente precisa receber o mesmo prato hoje e daqui a um mês, não importa quem fez.\n\nPor isso:\n- siga a ficha, sem mudar por conta própria;\n- use balança e medidas, não o olho;\n- se achar que dá para melhorar, fale com o líder;\n- se a ficha estiver sem informação, avise o líder.\n\nMudar a quantidade também muda o custo. Porção maior sem querer é prejuízo.","questoes":[{"tipo":"prova","enunciado":"Por que usar balança no preparo?","opcoes":["Para manter o padrão e o custo","Porque a cozinha exige, sem motivo","Só para o cliente ver"],"correta":0,"explicacao":"Sem medida, não há padrão nem controle de custo.","chave":"c-pre-2-q1","ordem":1},{"tipo":"situacao","enunciado":"Você acha que o molho ficaria melhor com mais sal do que pede a ficha.","opcoes":["Colocar mais sal","Seguir a ficha e sugerir ao líder","Mudar só hoje para testar"],"correta":1,"explicacao":"Mudança passa pelo líder, para valer para todos.","chave":"c-pre-2-q2","ordem":2}],"fontes":""},{"chave":"c-pre-3","titulo":"Recebimento, estoque e etiquetas","duracao_minutos":6,"conteudo":"Ao receber mercadoria:\n- local limpo e protegido;\n- embalagem íntegra;\n- validade conferida;\n- temperatura conferida no que precisa de frio;\n- produto com problema não entra: avise o líder.\n\nNo estoque, registre toda entrada e retirada no Héfisto. Se você tirou e não lançou, o número fica errado, e alguém vai comprar errado.\n\nNas prateleiras, nada direto no chão. Guarde com a validade à vista.","questoes":[{"tipo":"prova","enunciado":"A embalagem de um produto chegou violada. O que fazer?","opcoes":["Aceitar e usar logo","Não aceitar e chamar o líder","Trocar de embalagem"],"correta":1,"explicacao":"Embalagem íntegra é item da conferência.","chave":"c-pre-3-q1","ordem":1},{"tipo":"prova","enunciado":"Você retirou um produto do estoque. O que fazer?","opcoes":["Lançar a retirada no Héfisto","Avisar no fim do mês","Nada, se for pouco"],"correta":0,"explicacao":"O estoque só está certo se tudo for lançado.","chave":"c-pre-3-q2","ordem":2}],"fontes":"Anvisa, RDC 216/2004 (Boas Práticas para Serviços de Alimentação). Confira também as regras da vigilância sanitária da sua cidade."}]},{"chave":"c-servico","area":"cozinha","ordem":130,"titulo":"Hora do serviço","descricao":"Pedido entra, prato sai certo e na hora.","tipo":"aulas","aulas":[{"chave":"c-ser-1","titulo":"Pedido, tempo e comunicação","duracao_minutos":6,"conteudo":"No serviço, atenção vale mais que pressa.\n\n- Acompanhe os pedidos na tela da cozinha (KDS).\n- Confirme em voz alta o que vai fazer.\n- Avise quanto tempo falta quando perguntarem.\n- Termine os pratos da mesma mesa juntos.\n- Avise imediatamente se faltar um ingrediente.\n- Antes de sair, olhe o prato: limpo, completo, igual ao padrão e na temperatura certa.\n\nPrato duvidoso não sai. Refazer custa menos que perder o cliente.","questoes":[{"tipo":"prova","enunciado":"O que conferir antes do prato sair?","opcoes":["Só se está quente","Se está limpo, completo, no padrão e na temperatura certa","Só a aparência"],"correta":1,"explicacao":"O prato só sai quando tudo está certo.","chave":"c-ser-1-q1","ordem":1},{"tipo":"situacao","enunciado":"Acabou um ingrediente de um prato do cardápio em pleno serviço.","opcoes":["Trocar por outro sem avisar","Avisar o líder e o salão na hora","Atrasar o pedido sem falar nada"],"correta":1,"explicacao":"O salão precisa saber para não vender mais e oferecer alternativa.","chave":"c-ser-1-q2","ordem":2}],"fontes":""},{"chave":"c-ser-2","titulo":"Quando o prato volta","duracao_minutos":5,"conteudo":"Prato devolvido não é ataque pessoal. É uma informação.\n\n1. Escute o que o salão trouxe.\n2. Avise o líder.\n3. Refaça com prioridade.\n4. Olhe o motivo com calma depois do serviço.\n\nComida que voltou da mesa do cliente não é reaproveitada.\n\nSe houver suspeita de alimento estragado ou objeto no prato, guarde o prato e chame o líder. Não jogue fora antes de ele ver.","questoes":[{"tipo":"situacao","enunciado":"Um prato voltou porque o cliente achou um cabelo.","opcoes":["Tirar o cabelo e devolver","Guardar o prato, chamar o líder e refazer","Dizer que não é da cozinha"],"correta":1,"explicacao":"Refaça do zero e deixe o líder ver o que aconteceu.","chave":"c-ser-2-q1","ordem":1},{"tipo":"prova","enunciado":"O que fazer com a comida que voltou da mesa?","opcoes":["Reaproveitar","Servir aos funcionários","Não reaproveitar"],"correta":2,"explicacao":"Depois de ir à mesa, o alimento não retorna ao preparo.","chave":"c-ser-2-q2","ordem":2}],"fontes":""}]},{"chave":"c-coccao","area":"cozinha","ordem":140,"titulo":"Cocção e padrão","descricao":"Para cozinheiros: controlar fogo, tempo e finalização.","tipo":"aulas","aulas":[{"chave":"c-coc-1","titulo":"Controlar a cocção","duracao_minutos":7,"conteudo":"Cozinheiro controla três coisas: temperatura, tempo e ponto.\n\n- Aqueça a panela antes de selar. Panela fria solta água e não doura.\n- Não encha demais a panela ou a fritadeira: a temperatura cai.\n- Prove antes de servir, sempre com colher limpa.\n- Lembre: todas as partes do alimento precisam atingir 70 °C, a não ser que a casa tenha outro procedimento validado.\n\nMolhos, caldos e bases também têm ficha. Mantenha-os na temperatura certa durante o serviço e resfrie rápido o que sobrar.","questoes":[{"tipo":"prova","enunciado":"Por que não encher demais a fritadeira?","opcoes":["Porque a temperatura do óleo cai","Porque gasta menos óleo","Porque frita mais rápido"],"correta":0,"explicacao":"Com muita comida, o óleo esfria e o alimento encharca.","chave":"c-coc-1-q1","ordem":1},{"tipo":"prova","enunciado":"Como provar a comida?","opcoes":["Com a colher da panela, devolvendo depois","Com colher limpa a cada vez","Com o dedo limpo"],"correta":1,"explicacao":"Colher usada volta com contaminação.","chave":"c-coc-1-q2","ordem":2},{"tipo":"situacao","enunciado":"O centro da peça não chegou à temperatura e o pedido está atrasado.","opcoes":["Mandar assim mesmo","Terminar a cocção e avisar sobre o atraso","Trocar o prato sem avisar"],"correta":1,"explicacao":"Segurança vem antes de pressa. Avise o salão.","chave":"c-coc-1-q3","ordem":3}],"fontes":"Anvisa, RDC 216/2004 (Boas Práticas para Serviços de Alimentação). Confira também as regras da vigilância sanitária da sua cidade."},{"chave":"c-coc-2","titulo":"Finalização e empratamento","duracao_minutos":5,"conteudo":"O prato é a assinatura da casa. Monte igual à foto e ao guia de montagem.\n\n- Limpe a borda do prato.\n- Respeite o tamanho da porção.\n- Coloque cada item no lugar definido.\n- Confira quente com quente e frio com frio.\n\nSe o guia não tiver foto ou passo a passo, peça ao líder para completar a ficha. Ninguém deve montar pela memória de outra pessoa.","questoes":[{"tipo":"prova","enunciado":"O guia de um prato está incompleto. O que fazer?","opcoes":["Montar do seu jeito","Pedir ao líder para completar","Tirar o prato da lista"],"correta":1,"explicacao":"O guia completo evita que cada pessoa monte diferente.","chave":"c-coc-2-q1","ordem":1}],"fontes":""}]},{"chave":"p-coz-conhecer","area":"cozinha","ordem":150,"titulo":"Conhecer os pratos","descricao":"Todos os pratos da cozinha, com o que vai em cada um.","tipo":"pratos","departamento":"cozinha","etapa":"conhecer","aulas":[]},{"chave":"p-coz-montar","area":"cozinha","ordem":160,"titulo":"Como montar cada prato","descricao":"Ingredientes, guia de montagem e foto. O líder confirma quando você monta sozinho.","tipo":"pratos","departamento":"cozinha","etapa":"montar","aulas":[]},{"chave":"p-coz-preparar","area":"cozinha","ordem":170,"titulo":"Como cozinhar cada prato","descricao":"Modo de preparo de cada ficha. O líder confirma quando você faz sozinho.","tipo":"pratos","departamento":"cozinha","etapa":"preparar","aulas":[]},{"chave":"b-conhecer","area":"bar","ordem":210,"titulo":"Conhecendo o bar","descricao":"A estação, os insumos e a rotina.","tipo":"aulas","aulas":[{"chave":"b-con-1","titulo":"A estação de trabalho","duracao_minutos":6,"conteudo":"Seu líder vai mostrar o bar inteiro. Aprenda onde ficam:\n- garrafas de uso, reposição e estoque;\n- copos e taças de cada drink;\n- gelo, xaropes, sucos e guarnições;\n- coqueteleiras, dosadores, colheres e coadores.\n\nUma estação bem montada deixa tudo a um passo de distância. Devolva cada coisa ao lugar. Isso economiza minutos no pico.\n\n[PREENCHER: como a estação do bar é organizada na casa.]","questoes":[{"tipo":"prova","enunciado":"Por que devolver tudo ao mesmo lugar?","opcoes":["Para trabalhar mais rápido no pico","Só para ficar bonito","Para o gerente não reclamar"],"correta":0,"explicacao":"Na correria, você não pode procurar nada.","chave":"b-con-1-q1","ordem":1}],"fontes":""},{"chave":"b-con-2","titulo":"Abertura, fechamento e limpeza","duracao_minutos":6,"conteudo":"Abertura:\n- confira o checklist;\n- abasteça gelo, frutas, sucos e xaropes;\n- veja a validade do que foi aberto;\n- prepare as guarnições do dia;\n- deixe copos limpos e secos.\n\nFechamento:\n- guarde e identifique os preparos;\n- limpe bancada, pia e máquina;\n- lave os utensílios;\n- confira a reposição para o próximo turno.\n\nGelo também é alimento: use a pá, nunca o copo nem a mão. Se cair vidro perto do gelo, descarte todo o gelo daquele recipiente.","questoes":[{"tipo":"prova","enunciado":"Como pegar gelo?","opcoes":["Com o próprio copo","Com a pá de gelo","Com a mão limpa"],"correta":1,"explicacao":"Copo pode quebrar dentro do gelo. Mão contamina.","chave":"b-con-2-q1","ordem":1},{"tipo":"situacao","enunciado":"Uma taça quebrou perto do balde de gelo.","opcoes":["Tirar os cacos visíveis","Descartar todo o gelo e limpar o balde","Servir só de cima"],"correta":1,"explicacao":"Um caco invisível no drink pode ferir o cliente.","chave":"b-con-2-q2","ordem":2}],"fontes":""}]},{"chave":"b-tecnica","area":"bar","ordem":220,"titulo":"Técnica e padrão dos drinks","descricao":"Medir, bater, mexer, servir.","tipo":"aulas","aulas":[{"chave":"b-tec-1","titulo":"Medida e ficha","duracao_minutos":5,"conteudo":"A ficha de drink define os ingredientes, a dose, o copo, o gelo e a guarnição. Siga sempre, inclusive quando estiver sem movimento.\n\n- Meça com dosador. Olhar não é medida.\n- Use o gelo indicado.\n- Confira o copo antes de começar.\n- Prove com canudo limpo quando for necessário ajustar.\n\nDrink forte demais, fraco demais ou diferente da última vez faz o cliente desconfiar. Dose a mais também é prejuízo.","questoes":[{"tipo":"prova","enunciado":"Por que usar dosador?","opcoes":["Para manter o padrão e o custo","Só para quem está aprendendo","Porque fica bonito no balcão"],"correta":0,"explicacao":"Até o melhor bartender mede.","chave":"b-tec-1-q1","ordem":1},{"tipo":"situacao","enunciado":"Um cliente amigo pede para você carregar na dose por conta da casa.","opcoes":["Colocar dose extra","Explicar com gentileza que segue a ficha e falar com o líder se precisar","Cobrar uma gorjeta"],"correta":1,"explicacao":"Dose extra é prejuízo e foge do padrão.","chave":"b-tec-1-q2","ordem":2}],"fontes":""},{"chave":"b-tec-2","titulo":"Bater, mexer e montar","duracao_minutos":6,"conteudo":"O método da ficha muda o drink:\n\n- Batido (shake): para misturar ingredientes densos, como sucos, xaropes e cremes, resfriando e diluindo.\n- Mexido (stir): para drinks só de bebidas, com menos ar e mais transparência.\n- Montado (build): direto no copo.\n- Macerado: amassar com cuidado para extrair aroma, sem destruir o ingrediente.\n- Coado: retira gelo e pedaços.\n\nGelo faz parte da receita. Pouco gelo derrete rápido e aguada o drink.","questoes":[{"tipo":"prova","enunciado":"Qual método é mais usado para drinks só com bebidas, sem suco?","opcoes":["Batido","Mexido","Macerado"],"correta":1,"explicacao":"Mexer resfria com menos ar e mantém o drink limpo.","chave":"b-tec-2-q1","ordem":1},{"tipo":"prova","enunciado":"Por que não economizar gelo?","opcoes":["Pouco gelo derrete rápido e aguada o drink","Porque o gelo é barato","Porque o copo fica mais pesado"],"correta":0,"explicacao":"Mais gelo mantém a temperatura e dilui mais devagar.","chave":"b-tec-2-q2","ordem":2}],"fontes":""},{"chave":"b-tec-3","titulo":"Serviço no balcão","duracao_minutos":5,"conteudo":"No balcão, você é bartender e atendente ao mesmo tempo.\n\n- Cumprimente quem chegou, mesmo sem poder atender na hora: um olhar já diz \"já vou\".\n- Mantenha o balcão seco e limpo.\n- Sirva pelo lado certo, com o copo limpo e seco por fora.\n- Saiba explicar o sabor de cada drink em uma frase.\n- Registre tudo no sistema antes de entregar.\n\nPedidos que chegam do salão têm a mesma atenção. Veja a tela do bar.","questoes":[{"tipo":"prova","enunciado":"Quando registrar o pedido?","opcoes":["No fim do turno","Antes de entregar","Só se o cliente pedir a conta"],"correta":1,"explicacao":"O que não foi registrado se perde e vira prejuízo.","chave":"b-tec-3-q1","ordem":1},{"tipo":"situacao","enunciado":"Há gente esperando e você está no meio de um drink.","opcoes":["Fingir que não viu","Olhar, cumprimentar e dizer que já atende","Largar o drink na hora"],"correta":1,"explicacao":"Reconhecer a pessoa acalma a espera.","chave":"b-tec-3-q2","ordem":2}],"fontes":""}]},{"chave":"b-responsavel","area":"bar","ordem":230,"titulo":"Serviço responsável","descricao":"Quando não servir, e como fazer isso direito.","tipo":"aulas","aulas":[{"chave":"b-res-1","titulo":"Menores de 18 anos","duracao_minutos":4,"conteudo":"Vender, servir ou entregar bebida alcoólica a menor de 18 anos é crime, mesmo de graça e mesmo que um adulto peça para ele.\n\nNa dúvida sobre a idade:\n- peça um documento com foto, com educação;\n- sem documento, não sirva;\n- bebida para o maior que vai passar para o menor também não pode.\n\nNão negocie. Ofereça uma opção sem álcool e chame o líder se o cliente insistir.","questoes":[{"tipo":"prova","enunciado":"Um pai pede cerveja para o filho de 16 anos. O que fazer?","opcoes":["Servir, porque o pai autorizou","Servir só um copo","Não servir e oferecer opção sem álcool"],"correta":2,"explicacao":"Autorização dos pais não muda a regra.","chave":"b-res-1-q1","ordem":1},{"tipo":"situacao","enunciado":"Um jovem sem documento pede um gin, e você tem dúvida da idade.","opcoes":["Servir, pois ele parece adulto","Não servir sem documento e chamar o líder se insistir","Servir pouca bebida"],"correta":1,"explicacao":"Sem comprovar a idade, não sirva.","chave":"b-res-1-q2","ordem":2}],"fontes":"Estatuto da Criança e do Adolescente, art. 243 (Lei 13.106/2015)."},{"chave":"b-res-2","titulo":"Cliente embriagado","duracao_minutos":5,"conteudo":"Sinais: fala arrastada, perda de equilíbrio, voz alta, irritação, confusão.\n\nQuando notar:\n1. Avise o líder.\n2. Pare de oferecer álcool.\n3. Ofereça água e algo para comer.\n4. Se ele pedir mais, diga em voz baixa e com respeito que não pode servir.\n5. Nunca discuta, não toque na pessoa e não exponha o cliente.\n\nSe ele for dirigir, avise o líder para ajudar a chamar um carro ou contato.","questoes":[{"tipo":"prova","enunciado":"Quem decide como lidar com cliente embriagado?","opcoes":["Só você","O líder deve ser avisado","Os outros clientes"],"correta":1,"explicacao":"Essa situação não deve ser resolvida sozinho.","chave":"b-res-2-q1","ordem":1},{"tipo":"situacao","enunciado":"Um cliente visivelmente embriagado exige outra dose e levanta a voz.","opcoes":["Servir para evitar confusão","Discutir na frente de todos","Manter a calma, recusar com respeito, oferecer água e chamar o líder"],"correta":2,"explicacao":"Calma, respeito e o líder ao lado.","chave":"b-res-2-q2","ordem":2}],"fontes":""}]},{"chave":"b-organizacao","area":"bar","ordem":240,"titulo":"Estoque e perdas do bar","descricao":"Reposição, validade e controle.","tipo":"aulas","aulas":[{"chave":"b-org-1","titulo":"Reposição e estoque","duracao_minutos":5,"conteudo":"Bebida parada é dinheiro parado. Bebida perdida é dinheiro jogado fora.\n\n- Lance entrada e retirada no Héfisto, sempre.\n- Identifique sucos, xaropes e frutas com etiqueta e validade.\n- O que vence primeiro sai primeiro.\n- Registre quebra, perda ou drink descartado. Não esconda.\n- Avise antes que um item acabe.\n\nQuebrar uma garrafa é acidente. Esconder é problema.","questoes":[{"tipo":"prova","enunciado":"Uma garrafa caiu e quebrou. O que fazer?","opcoes":["Registrar a perda e avisar o líder","Esconder","Pagar do bolso sem falar nada"],"correta":0,"explicacao":"O registro mantém o estoque certo.","chave":"b-org-1-q1","ordem":1},{"tipo":"prova","enunciado":"Quando lançar a retirada de uma bebida do estoque?","opcoes":["No fim do mês","Sempre que retirar","Só em garrafas caras"],"correta":1,"explicacao":"Retirada sem lançamento deixa o estoque errado.","chave":"b-org-1-q2","ordem":2},{"tipo":"situacao","enunciado":"O xarope aberto está sem etiqueta.","opcoes":["Usar, pois parece bom","Separar e chamar o líder","Etiquetar com a data de hoje"],"correta":1,"explicacao":"Sem data, ninguém sabe a validade.","chave":"b-org-1-q3","ordem":3}],"fontes":""}]},{"chave":"p-bar-conhecer","area":"bar","ordem":250,"titulo":"Conhecer os drinks","descricao":"Todos os drinks da casa, com o que vai em cada um.","tipo":"pratos","departamento":"bar","etapa":"conhecer","aulas":[]},{"chave":"p-bar-montar","area":"bar","ordem":260,"titulo":"Como montar cada drink","descricao":"Ingredientes, copo, gelo, método e guarnição. O líder confirma quando você faz sozinho.","tipo":"pratos","departamento":"bar","etapa":"montar","aulas":[]},{"chave":"p-bar-preparar","area":"bar","ordem":270,"titulo":"Como preparar as bases","descricao":"Xaropes e preparos do bar. O líder confirma quando você faz sozinho.","tipo":"pratos","departamento":"bar","etapa":"preparar","aulas":[]},{"chave":"s-conhecer","area":"salao","ordem":310,"titulo":"Conhecendo o salão","descricao":"Mesas, setores e rotina.","tipo":"aulas","aulas":[{"chave":"s-con-1","titulo":"O salão e a rotina","duracao_minutos":6,"conteudo":"Seu líder vai apresentar o salão. Aprenda:\n- número de cada mesa e setor;\n- onde ficam talheres, guardanapos, cardápios e materiais;\n- como chegar à cozinha e ao bar sem atrapalhar o cliente;\n- quem atende cada setor.\n\nAntes de abrir, siga o checklist: mesas limpas e alinhadas, cadeiras firmes, cardápios limpos, banheiro conferido, som e luz ajustados.\n\nDepois que o cliente sai, a mesa volta ao padrão o mais rápido possível.\n\n[PREENCHER: mapa das mesas e setores da casa.]","questoes":[{"tipo":"prova","enunciado":"Por que decorar o número das mesas?","opcoes":["Para entregar o pedido certo sem perguntar","Para limpar menos","Não é necessário"],"correta":0,"explicacao":"Saber a mesa evita erro e demora.","chave":"s-con-1-q1","ordem":1},{"tipo":"prova","enunciado":"O que fazer antes de abrir o salão?","opcoes":["Seguir o checklist de abertura","Esperar o primeiro cliente","Só acender as luzes"],"correta":0,"explicacao":"O checklist garante que nada foi esquecido.","chave":"s-con-1-q2","ordem":2},{"tipo":"situacao","enunciado":"Faltando 5 minutos para abrir, você vê uma cadeira quebrada em uma mesa reservada.","opcoes":["Deixar como está","Trocar a cadeira e avisar o líder","Esconder o defeito com uma almofada"],"correta":1,"explicacao":"Segurança do cliente primeiro. O líder precisa saber do defeito.","chave":"s-con-1-q3","ordem":3}],"fontes":""}]},{"chave":"s-apoio","area":"salao","ordem":315,"titulo":"Apoio ao salão","descricao":"O trabalho do cumim, que sustenta o serviço.","tipo":"aulas","aulas":[{"chave":"s-apo-1","titulo":"Mesa, talheres e retirada","duracao_minutos":6,"conteudo":"O cumim mantém o salão funcionando.\n\n- Pegue talheres pelo cabo e taças pela haste ou pela base.\n- Polir é tirar marcas com pano limpo e seco.\n- Retire pratos só quando todos à mesa terminarem, salvo pedido do cliente.\n- Pergunte com discrição: \"posso retirar?\"\n- Mantenha as praças abastecidas.\n- Ajude o garçom sem interromper a conversa do cliente.","questoes":[{"tipo":"prova","enunciado":"Como segurar uma taça limpa?","opcoes":["Pela boca","Pela haste ou pela base","Com os dedos dentro"],"correta":1,"explicacao":"Ninguém quer beber onde um dedo tocou.","chave":"s-apo-1-q1","ordem":1},{"tipo":"prova","enunciado":"Quando retirar os pratos da mesa?","opcoes":["Assim que o primeiro terminar","Quando todos terminarem, salvo pedido do cliente","No momento da conta"],"correta":1,"explicacao":"Retirar cedo apressa quem ainda está comendo.","chave":"s-apo-1-q2","ordem":2},{"tipo":"situacao","enunciado":"Um cliente pede a você um prato do cardápio, e o garçom dele está longe.","opcoes":["Dizer que não é sua função","Avisar o garçom na hora, com gentileza","Anotar e esquecer"],"correta":1,"explicacao":"Para o cliente, todos somos a casa.","chave":"s-apo-1-q3","ordem":3}],"fontes":""}]},{"chave":"s-atendimento","area":"salao","ordem":320,"titulo":"A sequência do atendimento","descricao":"Do bom-dia ao até logo.","tipo":"aulas","aulas":[{"chave":"s-ate-1","titulo":"Receber e apresentar","duracao_minutos":6,"conteudo":"A primeira impressão acontece nos primeiros segundos.\n\n1. Receba com sorriso e contato visual.\n2. Conduza até a mesa, sem andar rápido demais.\n3. Entregue o cardápio e apresente-se.\n4. Ofereça água e bebidas.\n5. Conte as sugestões do dia e o que acabou.\n6. Dê tempo para escolher, mas fique por perto.\n\nNunca deixe a mesa sem atendimento porque \"não é do seu setor\". Avise o colega ou atenda.","questoes":[{"tipo":"prova","enunciado":"O que informar logo ao chegar à mesa?","opcoes":["Os pratos do dia e o que acabou","O salário da equipe","Só o preço mais alto"],"correta":0,"explicacao":"Evita a frustração de pedir o que não tem.","chave":"s-ate-1-q1","ordem":1},{"tipo":"situacao","enunciado":"Uma mesa chega no meio da correria e seu setor está cheio.","opcoes":["Ignorar até ter tempo","Cumprimentar, deixar o cardápio e dizer que já volta","Pedir que voltem depois"],"correta":1,"explicacao":"Reconhecer a mesa acalma a espera.","chave":"s-ate-1-q2","ordem":2}],"fontes":""},{"chave":"s-ate-2","titulo":"Pedido, entrega e acompanhamento","duracao_minutos":7,"conteudo":"Pedido:\n- anote e repita para confirmar;\n- pergunte sobre alergias ou restrições;\n- confirme ponto, acompanhamento e bebida;\n- lance imediatamente no sistema, na mesa certa.\n\nEntrega:\n- leve os pratos juntos;\n- sirva sem perguntar \"de quem é\";\n- diga o nome do prato ao colocar na mesa.\n\nAcompanhamento:\n- em até dois minutos, veja se está tudo certo;\n- ofereça mais bebida antes de o copo esvaziar;\n- retire o que não está em uso;\n- ofereça sobremesa e café.\n\nConta:\n- leve quando pedirem, sem deixar o cliente esperando;\n- confira a conta antes de levar;\n- agradeça e convide para voltar.","questoes":[{"tipo":"prova","enunciado":"Quando lançar o pedido no sistema?","opcoes":["Imediatamente","Quando a cozinha pedir","No fim do turno"],"correta":0,"explicacao":"Cada minuto de atraso é um minuto na espera do cliente.","chave":"s-ate-2-q1","ordem":1},{"tipo":"prova","enunciado":"O que perguntar sempre ao anotar o pedido?","opcoes":["Sobre alergias e restrições","A idade do cliente","Quanto ele pretende gastar"],"correta":0,"explicacao":"Essa pergunta pode salvar uma vida.","chave":"s-ate-2-q2","ordem":2},{"tipo":"situacao","enunciado":"O cliente pede o bife ao ponto e você esqueceu de anotar o ponto.","opcoes":["Deixar a cozinha decidir","Voltar à mesa e confirmar antes de lançar","Lançar como bem passado"],"correta":1,"explicacao":"Confirmar custa um minuto. Refazer custa muito mais.","chave":"s-ate-2-q3","ordem":3}],"fontes":""}]},{"chave":"s-comportamento","area":"salao","ordem":330,"titulo":"Comportamento do garçom","descricao":"Como se portar diante do cliente.","tipo":"aulas","aulas":[{"chave":"s-com-1","titulo":"Postura e aparência","duracao_minutos":5,"conteudo":"O garçom é a cara da casa. O cliente lê tudo em você.\n\n- Uniforme limpo e completo, sapato limpo, cabelo arrumado, unhas limpas e sem perfume forte.\n- Coluna reta, mãos livres, nada de encostar em paredes ou mesas.\n- Não mexa no celular.\n- Não coma nem masque chiclete à vista.\n- Não converse alto com colegas nem fale de cliente perto de outro cliente.\n- Olhe sempre para o salão: a mesa não deve precisar chamar você.\n\nNunca toque no cliente, sente-se à mesa ou entre na conversa dele sem ser convidado.","questoes":[{"tipo":"prova","enunciado":"Como saber que uma mesa precisa de algo?","opcoes":["Esperar chamar","Olhar sempre para o salão","Perguntar a cada minuto"],"correta":1,"explicacao":"Serviço bom se antecipa.","chave":"s-com-1-q1","ordem":1},{"tipo":"prova","enunciado":"O que não se faz diante do cliente?","opcoes":["Sorrir","Falar de outro cliente","Agradecer"],"correta":1,"explicacao":"O que você diz de um cliente perto de outro afasta os dois.","chave":"s-com-1-q2","ordem":2}],"fontes":""},{"chave":"s-com-2","titulo":"Como falar com o cliente","duracao_minutos":5,"conteudo":"Linguagem:\n- diga \"senhor\" e \"senhora\" até o cliente pedir outro tratamento;\n- não use gírias nem apelidos, como \"amigão\" ou \"querida\";\n- fale \"acabou por hoje\", nunca \"sei lá\";\n- nunca diga \"não é comigo\";\n- nunca discuta nem responda com ironia.\n\nTrate todas as mesas com a mesma atenção, não importa a roupa, a cor, a idade, a conta ou quem acompanha o cliente.\n\nSe o cliente for mal-educado, mantenha o tom, respire e, se for preciso, chame o líder. Não responda no mesmo nível.","questoes":[{"tipo":"prova","enunciado":"Qual frase é adequada?","opcoes":["Isso não é comigo","Vou verificar e já retorno","Sei lá"],"correta":1,"explicacao":"Mostre que vai resolver, mesmo sem saber a resposta.","chave":"s-com-2-q1","ordem":1},{"tipo":"situacao","enunciado":"Um cliente fala de forma grosseira com você.","opcoes":["Responder no mesmo tom","Manter a calma, resolver o que puder e chamar o líder se preciso","Ignorar a mesa"],"correta":1,"explicacao":"Você representa a casa. O líder ajuda quando passar do limite.","chave":"s-com-2-q2","ordem":2},{"tipo":"situacao","enunciado":"Um cliente faz uma cantada ou comentário que deixa você desconfortável.","opcoes":["Aguentar calado","Sair da situação e avisar o líder, que assume a mesa","Xingar o cliente"],"correta":1,"explicacao":"Ninguém precisa aceitar assédio. O líder assume.","chave":"s-com-2-q3","ordem":3}],"fontes":""}]},{"chave":"s-mesas","area":"salao","ordem":318,"titulo":"Como montar as mesas","descricao":"A mesa pronta para receber o cliente.","tipo":"aulas","aulas":[{"chave":"s-mes-1","titulo":"A mesa padrão","duracao_minutos":6,"conteudo":"Uma mesa bem montada mostra cuidado antes do primeiro pedido.\n\nAntes de montar:\n- limpe e seque o tampo;\n- confira se a mesa não balança;\n- alinhe as cadeiras;\n- confira toalha ou jogo americano, sem manchas.\n\nA posição clássica dos itens:\n- garfo à esquerda do prato;\n- faca à direita, com o fio voltado para o prato;\n- colher, quando houver, à direita da faca;\n- copo de água acima da ponta da faca;\n- taça de vinho ao lado do copo de água, quando fizer parte do serviço;\n- guardanapo limpo e dobrado.\n\nTalheres e taças são pegos pelo cabo e pela haste. Confira contra a luz antes de colocar na mesa.\n\n[PREENCHER: o padrão de mesa da casa: louça, guardanapo, itens fixos e foto da mesa pronta.]","questoes":[{"tipo":"prova","enunciado":"Onde fica o garfo na posição clássica?","opcoes":["À esquerda do prato","À direita do prato","Em cima do prato"],"correta":0,"explicacao":"Garfo à esquerda, faca e colher à direita.","chave":"s-mes-1-q1","ordem":1},{"tipo":"prova","enunciado":"Para que lado fica o fio da faca?","opcoes":["Para fora","Para o prato","Para cima"],"correta":1,"explicacao":"O fio fica voltado para o prato.","chave":"s-mes-1-q2","ordem":2},{"tipo":"situacao","enunciado":"A mesa está pronta, mas a taça tem uma marca de dedo.","opcoes":["Deixar assim","Trocar ou polir antes de abrir","Virar a marca para o outro lado"],"correta":1,"explicacao":"A taça é a primeira coisa que o cliente vê de perto.","chave":"s-mes-1-q3","ordem":3}],"fontes":""},{"chave":"s-mes-2","titulo":"Reposição entre clientes","duracao_minutos":5,"conteudo":"Entre um cliente e outro, a mesa volta ao padrão.\n\n1. Retire tudo da mesa.\n2. Limpe tampo e cadeiras, inclusive os farelos do assento.\n3. Remonte a mesa com itens limpos.\n4. Alinhe as cadeiras.\n5. Avise que a mesa está liberada.\n\nFaça isso rápido e sem barulho. Quem está nas outras mesas não precisa ouvir talheres caindo.\n\nEm mesa para mais pessoas, confira o número de lugares da reserva antes de montar.","questoes":[{"tipo":"prova","enunciado":"O que limpar além do tampo?","opcoes":["Nada","As cadeiras, inclusive o assento","Só o chão"],"correta":1,"explicacao":"Farelo no assento é a primeira coisa que o próximo cliente sente.","chave":"s-mes-2-q1","ordem":1}],"fontes":""}]},{"chave":"s-bebidas","area":"salao","ordem":335,"titulo":"Como servir vinho e outras bebidas","descricao":"O serviço correto de cada bebida à mesa.","tipo":"aulas","aulas":[{"chave":"s-beb-1","titulo":"Servir vinho","duracao_minutos":7,"conteudo":"Sequência do serviço de vinho:\n1. Apresente a garrafa a quem pediu, com o rótulo à vista, e confirme nome e safra.\n2. Sobre o aparador ou a mesa, corte a cápsula abaixo da borda do gargalo.\n3. Use o saca-rolhas sem girar a garrafa e tire a rolha sem barulho.\n4. Limpe o gargalo com um guardanapo.\n5. Sirva uma pequena dose para quem pediu provar.\n6. Com a aprovação, sirva as outras pessoas e termine em quem provou.\n7. Sirva sem encher a taça: cerca de um terço, para o vinho poder respirar.\n8. Ao terminar, gire de leve a garrafa para não pingar.\n\nSegure a garrafa pelo corpo, sem cobrir o rótulo, e não encoste o gargalo na taça.\n\nTemperaturas de referência:\n- espumantes: de 6 °C a 8 °C;\n- brancos e rosés: de 8 °C a 12 °C;\n- tintos leves: de 12 °C a 14 °C;\n- tintos encorpados: de 16 °C a 18 °C.\n\nSe o cliente disser que o vinho está com defeito ou cheiro ruim, não discuta. Chame o líder.","questoes":[{"tipo":"prova","enunciado":"Quem prova o vinho primeiro?","opcoes":["A pessoa mais velha","Quem pediu o vinho","Quem estiver mais perto"],"correta":1,"explicacao":"Quem pediu aprova, e por último completa a própria taça.","chave":"s-beb-1-q1","ordem":1},{"tipo":"prova","enunciado":"Quanto servir na taça?","opcoes":["Até a borda","Cerca de um terço","Apenas uma gota"],"correta":1,"explicacao":"Taça com espaço deixa o aroma aparecer.","chave":"s-beb-1-q2","ordem":2},{"tipo":"prova","enunciado":"Qual é a temperatura de referência para espumantes?","opcoes":["De 6 °C a 8 °C","De 16 °C a 18 °C","Temperatura ambiente"],"correta":0,"explicacao":"Espumantes são servidos bem gelados.","chave":"s-beb-1-q3","ordem":3},{"tipo":"situacao","enunciado":"O cliente prova e diz que o vinho está com gosto de mofo.","opcoes":["Explicar que vinho é assim mesmo","Retirar, pedir desculpas e chamar o líder","Provar na frente dele para discordar"],"correta":1,"explicacao":"O líder conduz a troca. Não discuta.","chave":"s-beb-1-q4","ordem":4}],"fontes":""},{"chave":"s-beb-2","titulo":"Abrir espumante com segurança","duracao_minutos":4,"conteudo":"Rolha de espumante sob pressão pode machucar.\n\n1. Mantenha a garrafa bem gelada e sem agitar.\n2. Tire a cápsula e solte a gaiola, sempre com o polegar sobre a rolha.\n3. Incline a garrafa e nunca aponte para ninguém.\n4. Segure a rolha e gire a garrafa devagar.\n5. Deixe a rolha sair com um suspiro, sem estouro.\n6. Sirva aos poucos, em duas etapas, para a espuma não transbordar.","questoes":[{"tipo":"prova","enunciado":"O que girar ao abrir o espumante?","opcoes":["A garrafa, segurando a rolha","Só a rolha, com força","Nada: basta puxar"],"correta":0,"explicacao":"Assim você controla a saída da rolha.","chave":"s-beb-2-q1","ordem":1},{"tipo":"situacao","enunciado":"Um colega quer estourar o espumante para animar a mesa.","opcoes":["Deixar","Abrir com controle, sem apontar para ninguém","Sacudir antes"],"correta":1,"explicacao":"A rolha pode ferir alguém.","chave":"s-beb-2-q2","ordem":2}],"fontes":""},{"chave":"s-beb-3","titulo":"Água, refrigerante, cerveja e café","duracao_minutos":5,"conteudo":"Água e refrigerante:\n- abra na mesa ou traga com o lacre à vista;\n- pergunte se quer gelo e limão;\n- sirva pela direita do cliente, com o copo na mesa.\n\nCerveja:\n- use copo limpo e seco;\n- incline o copo e endireite no final para formar colarinho;\n- ofereça a segunda antes de a garrafa acabar.\n\nCafé:\n- sirva quente, com a asa da xícara à direita do cliente;\n- leve açúcar e adoçante sem precisar pedir.\n\nNão encha o copo até a boca. Reponha antes de esvaziar. Bebida alcoólica segue as regras de serviço responsável.\n\n[PREENCHER: as bebidas da casa que têm serviço especial, como cachaças e bebidas regionais.]","questoes":[{"tipo":"prova","enunciado":"Como servir cerveja no copo?","opcoes":["Com o copo inclinado, endireitando no final","Com o copo reto desde o início","De bem alto, para fazer espuma"],"correta":0,"explicacao":"Assim o colarinho fica no ponto.","chave":"s-beb-3-q1","ordem":1},{"tipo":"prova","enunciado":"De que lado fica a asa da xícara?","opcoes":["À direita do cliente","À esquerda do cliente","Para a frente"],"correta":0,"explicacao":"A maioria pega com a direita.","chave":"s-beb-3-q2","ordem":2},{"tipo":"situacao","enunciado":"Você percebe que o copo de água de um cliente está quase vazio.","opcoes":["Esperar ele chamar","Oferecer mais antes de esvaziar","Trocar a mesa de setor"],"correta":1,"explicacao":"Serviço bom se antecipa.","chave":"s-beb-3-q3","ordem":3}],"fontes":""}]},{"chave":"s-cardapio","area":"salao","ordem":340,"titulo":"Cardápio e venda","descricao":"Conhecer e sugerir, sem empurrar.","tipo":"aulas","aulas":[{"chave":"s-car-1","titulo":"Vender é ajudar a escolher","duracao_minutos":6,"conteudo":"Você vende melhor quando sabe do que está falando.\n\n- Prove os pratos e drinks quando a casa oferecer.\n- Saiba explicar cada prato em uma frase: o que é, como vem, para quem combina.\n- Saiba o que tem pimenta, glúten, leite, camarão e outros alérgenos, consultando a ficha quando tiver dúvida.\n- Sugira com base no que o cliente disse.\n- Ofereça a bebida que combina, a entrada para dividir e a sobremesa no fim.\n\nNunca empurre o item mais caro. Cliente que se sente enganado não volta.","questoes":[{"tipo":"prova","enunciado":"O que você precisa saber sobre cada prato?","opcoes":["Só o preço","O que é, como vem e para quem combina","Só o nome"],"correta":1,"explicacao":"Com isso, você ajuda o cliente a escolher.","chave":"s-car-1-q1","ordem":1},{"tipo":"prova","enunciado":"Qual é a melhor sugestão?","opcoes":["A do prato mais caro, sempre","A que combina com o que o cliente disse","A que sobrou na cozinha"],"correta":1,"explicacao":"Boa sugestão parte do cliente.","chave":"s-car-1-q2","ordem":2},{"tipo":"situacao","enunciado":"O cliente pergunta sobre um prato que você nunca provou.","opcoes":["Inventar uma descrição","Dizer o que sabe pela ficha e pedir ajuda se preciso","Dizer para escolher outro"],"correta":1,"explicacao":"Nunca invente. Use a ficha ou chame quem sabe.","chave":"s-car-1-q3","ordem":3}],"fontes":""}]},{"chave":"s-situacoes","area":"salao","ordem":350,"titulo":"Situações inesperadas","descricao":"O método para resolver qualquer problema na mesa.","tipo":"aulas","aulas":[{"chave":"s-sit-1","titulo":"O método: OUVIR","duracao_minutos":6,"conteudo":"Quando algo sai errado, siga cinco passos:\n\nO: Ouça sem interromper. Olhe para o cliente.\nU: Use palavras de cuidado: \"peço desculpas, vou resolver agora\".\nV: Verifique o que aconteceu.\nI: Informe o líder e diga ao cliente o que será feito e quanto tempo levará.\nR: Resolva e volte à mesa para conferir.\n\nRegras:\n- não culpe a cozinha, o bar ou um colega;\n- não discuta quem tem razão;\n- não prometa o que você não pode cumprir;\n- descontos e cortesias só com o líder;\n- quanto mais cedo o líder souber, mais fácil é resolver.\n\nCliente com problema bem resolvido costuma confiar mais na casa do que cliente que nunca teve problema nenhum.","questoes":[{"tipo":"prova","enunciado":"Quem pode dar desconto ou cortesia?","opcoes":["Qualquer garçom","O líder","O cumim"],"correta":1,"explicacao":"Você chama o líder. Ele decide.","chave":"s-sit-1-q1","ordem":1},{"tipo":"prova","enunciado":"O que evitar ao ouvir uma reclamação?","opcoes":["Olhar para o cliente","Pedir desculpas","Culpar a cozinha"],"correta":2,"explicacao":"Para o cliente, a casa é uma só.","chave":"s-sit-1-q2","ordem":2},{"tipo":"situacao","enunciado":"O cliente reclama da demora e está irritado.","opcoes":["Dizer que a cozinha está lenta","Ouvir, pedir desculpas, verificar o pedido e informar o tempo real","Evitar passar perto da mesa"],"correta":1,"explicacao":"O silêncio piora tudo. Informe o tempo real.","chave":"s-sit-1-q3","ordem":3},{"tipo":"situacao","enunciado":"Você levou o prato errado para a mesa.","opcoes":["Convencer o cliente a aceitar","Pedir desculpas, retirar, avisar a cozinha e priorizar o certo","Trocar sem dizer nada"],"correta":1,"explicacao":"Assuma, peça prioridade e avise o líder.","chave":"s-sit-1-q4","ordem":4}],"fontes":""},{"chave":"s-sit-2","titulo":"Comida, bebida e acidentes","duracao_minutos":7,"conteudo":"Cabelo ou objeto no prato: peça desculpas, retire na hora, avise o líder e leve para a cozinha sem descartar.\n\nComida fria, passada ou diferente: ofereça refazer ou trocar e avise o líder.\n\nDerramou algo no cliente: peça desculpas, ofereça guardanapo limpo sem tocar nele e chame o líder.\n\nQuebrou algo: afaste as pessoas, limpe bem, com vassoura e pá, e cuide para que não sobrem cacos.\n\nCliente passou mal: chame o líder na hora, não dê remédio e, se for grave, ligue 192.\n\nReação alérgica (coceira, inchaço no rosto, falta de ar): chame o líder, ligue 192 imediatamente e guarde o prato. Não espere passar.\n\nEngasgo ou desmaio: chame ajuda e ligue 192. Quem tiver treinamento presta os primeiros socorros.","questoes":[{"tipo":"situacao","enunciado":"Um cliente encontra um cabelo no prato.","opcoes":["Dizer que não é da casa","Pedir desculpas, retirar, chamar o líder e refazer","Tirar o cabelo com um garfo"],"correta":1,"explicacao":"Retire e leve o prato para o líder ver.","chave":"s-sit-2-q1","ordem":1},{"tipo":"situacao","enunciado":"Você derrubou vinho na roupa de uma cliente.","opcoes":["Esfregar a roupa dela","Pedir desculpas, oferecer guardanapo e chamar o líder","Fingir que não foi você"],"correta":1,"explicacao":"O líder conduz a solução. Não toque na cliente.","chave":"s-sit-2-q2","ordem":2},{"tipo":"situacao","enunciado":"Depois de comer, um cliente fica com o rosto inchado e com falta de ar.","opcoes":["Dar um antialérgico","Esperar melhorar","Chamar o líder, ligar 192 e guardar o prato"],"correta":2,"explicacao":"Reação alérgica grave é emergência.","chave":"s-sit-2-q3","ordem":3},{"tipo":"situacao","enunciado":"Um cliente passa mal e pede um remédio para você.","opcoes":["Oferecer o seu remédio","Não dar remédio e chamar o líder","Mandar ir ao banheiro"],"correta":1,"explicacao":"Funcionário não dá remédio.","chave":"s-sit-2-q4","ordem":4}],"fontes":""},{"chave":"s-sit-3","titulo":"Conta, conflitos e imprevistos da casa","duracao_minutos":7,"conteudo":"Conta errada: peça desculpas, leve de volta, confira e corrija com o líder.\n\nTaxa de serviço: é opcional. Se o cliente não quiser pagar, leve o pedido ao caixa ou ao líder sem discutir.\n\nCliente saiu sem pagar: não corra atrás nem o enfrente. Avise o líder imediatamente.\n\nMesa pede para dividir a conta de um jeito difícil: confirme com calma e peça ajuda ao caixa.\n\nBriga entre clientes: não entre no meio. Chame o líder e proteja as outras mesas.\n\nCriança correndo no salão: fale com os pais com gentileza, explicando o perigo das bandejas.\n\nReserva não encontrada: peça desculpas, chame o líder e não discuta.\n\nSistema ou internet caiu: anote os pedidos em papel, com mesa e hora, e leve ao líder. Lance tudo quando voltar.\n\nFaltou luz: mantenha a calma, tranquilize as mesas, peça que fiquem nos lugares e aguarde o líder. Na cozinha, o líder decide o que fazer.\n\nPedido fora do cardápio: pergunte à cozinha ou ao líder antes de prometer.","questoes":[{"tipo":"situacao","enunciado":"O cliente saiu sem pagar e já está na calçada.","opcoes":["Correr atrás e segurá-lo","Avisar o líder imediatamente, sem enfrentar","Pagar do próprio bolso em silêncio"],"correta":1,"explicacao":"Sua segurança vem primeiro.","chave":"s-sit-3-q1","ordem":1},{"tipo":"situacao","enunciado":"O sistema caiu no pico do jantar.","opcoes":["Parar de atender","Anotar no papel com mesa e hora e avisar o líder","Mandar os pedidos de cabeça"],"correta":1,"explicacao":"Papel com mesa e hora mantém tudo funcionando.","chave":"s-sit-3-q2","ordem":2},{"tipo":"situacao","enunciado":"Dois clientes começam a discutir de forma agressiva.","opcoes":["Entrar no meio","Chamar o líder e afastar as outras mesas","Filmar"],"correta":1,"explicacao":"Não entre no meio. O líder conduz.","chave":"s-sit-3-q3","ordem":3},{"tipo":"situacao","enunciado":"O cliente não quer pagar a taxa de serviço.","opcoes":["Explicar que é obrigatória","Retirar sem discutir, com o caixa ou o líder","Insistir até ele pagar"],"correta":1,"explicacao":"A taxa é opcional. Sem discussão.","chave":"s-sit-3-q4","ordem":4},{"tipo":"situacao","enunciado":"Uma mesa pede um prato que não está no cardápio.","opcoes":["Prometer que sim","Dizer não na hora","Verificar com a cozinha ou o líder antes de responder"],"correta":2,"explicacao":"Só prometa o que a casa pode entregar.","chave":"s-sit-3-q5","ordem":5},{"tipo":"situacao","enunciado":"Faltou luz no meio do jantar.","opcoes":["Mandar todos embora","Manter a calma, tranquilizar as mesas e aguardar o líder","Sair para ver o que aconteceu"],"correta":1,"explicacao":"Sua calma acalma o salão.","chave":"s-sit-3-q6","ordem":6}],"fontes":""}]},{"chave":"p-sal-pratos","area":"salao","ordem":360,"titulo":"Os pratos que você vende","descricao":"O que vai em cada prato, para explicar ao cliente.","tipo":"pratos","departamento":"cozinha","etapa":"conhecer","aulas":[]},{"chave":"p-sal-drinks","area":"salao","ordem":370,"titulo":"Os drinks que você vende","descricao":"O que vai em cada drink, para explicar ao cliente.","tipo":"pratos","departamento":"bar","etapa":"conhecer","aulas":[]},{"chave":"l-lideranca","area":"gestao","ordem":410,"titulo":"Liderança de equipe","descricao":"Conduzir pessoas na correria.","tipo":"aulas","aulas":[{"chave":"l-lid-1","titulo":"Liderar pelo exemplo","duracao_minutos":6,"conteudo":"A equipe faz o que vê, não o que ouve.\n\n- Chegue antes, siga as regras e use o padrão que você cobra.\n- Dê instruções claras: o que fazer, até quando e como saber que ficou certo.\n- Elogie em público e corrija em particular.\n- Assuma os erros da sua área diante do dono e do cliente.\n- Decida com calma na correria. Equipe nervosa copia o líder nervoso.\n\nLiderar não é fazer tudo: é garantir que tudo seja bem feito. Se você faz tudo sozinho, a equipe não aprende e nada funciona sem você.","questoes":[{"tipo":"prova","enunciado":"Como corrigir um erro de alguém da equipe?","opcoes":["Em particular, com clareza","Na frente de todos, para servir de exemplo","Não corrigir, para evitar conflito"],"correta":0,"explicacao":"Correção em público humilha e não ensina.","chave":"l-lid-1-q1","ordem":1},{"tipo":"situacao","enunciado":"Um cozinheiro experiente ignora a ficha e diz que sempre fez assim.","opcoes":["Deixar, pois ele é experiente","Conversar em particular, explicar o motivo e cobrar o padrão","Gritar no meio do serviço"],"correta":1,"explicacao":"O padrão vale para todos. Explique o motivo.","chave":"l-lid-1-q2","ordem":2}],"fontes":""},{"chave":"l-lid-2","titulo":"Formar pessoas","duracao_minutos":6,"conteudo":"Você é responsável por formar quem chega.\n\nO método é simples:\n1. Mostre fazendo e explique por quê.\n2. Faça junto.\n3. Deixe a pessoa fazer e observe.\n4. Corrija na hora, com respeito.\n5. Quando ela fizer sozinha, com qualidade, várias vezes, aprove no Héfisto.\n\nAprove o que você viu. Marcar sem ter visto coloca o cliente e a equipe em risco.\n\nAcompanhe a sua equipe em Treinamento > Equipe. Faça pequenas conversas de retorno: o que foi bem, o que melhorar e o próximo passo.","questoes":[{"tipo":"prova","enunciado":"Quando aprovar um item prático?","opcoes":["Quando a pessoa disser que sabe","Quando você viu a pessoa fazer sozinha e com qualidade","Depois de 30 dias"],"correta":1,"explicacao":"O sistema confia na sua avaliação.","chave":"l-lid-2-q1","ordem":1},{"tipo":"situacao","enunciado":"Um novato tirou nota alta na prova, mas ainda erra na prática.","opcoes":["Aprovar por causa da nota","Não aprovar, treinar e reavaliar","Tirar da área sem conversar"],"correta":1,"explicacao":"A prática é onde o cliente sente a diferença.","chave":"l-lid-2-q2","ordem":2}],"fontes":""},{"chave":"l-lid-3","titulo":"Conflitos e conversas difíceis","duracao_minutos":6,"conteudo":"Conflito ignorado cresce.\n\n1. Converse logo, em particular.\n2. Fale do fato, não da pessoa: \"ontem você chegou 30 minutos depois\", não \"você é irresponsável\".\n3. Ouça o outro lado.\n4. Combine o que muda.\n5. Registre e acompanhe.\n\nAssédio, agressão, furto e desrespeito grave não são resolvidos entre colegas. Leve ao gerente ou ao dono no mesmo dia e registre o que aconteceu.","questoes":[{"tipo":"prova","enunciado":"Como começar uma conversa difícil?","opcoes":["Falando do fato","Falando do caráter da pessoa","Com uma indireta no grupo"],"correta":0,"explicacao":"Fato se resolve. Rótulo gera defesa.","chave":"l-lid-3-q1","ordem":1},{"tipo":"situacao","enunciado":"Dois funcionários discutem na frente de clientes.","opcoes":["Separar, retomar o serviço e conversar em particular depois","Dar razão a um deles na hora","Ignorar"],"correta":0,"explicacao":"Primeiro o serviço, depois a conversa.","chave":"l-lid-3-q2","ordem":2},{"tipo":"situacao","enunciado":"Uma funcionária relata assédio de um colega.","opcoes":["Pedir que ela resolva sozinha","Ouvir, proteger e levar ao dono no mesmo dia","Comentar com a equipe"],"correta":1,"explicacao":"É caso sério, com sigilo e rapidez.","chave":"l-lid-3-q3","ordem":3}],"fontes":""}]},{"chave":"l-organizacao","area":"gestao","ordem":420,"titulo":"Organização da área","descricao":"Rotina, escala, compras e números.","tipo":"aulas","aulas":[{"chave":"l-org-1","titulo":"A rotina do líder","duracao_minutos":6,"conteudo":"Um dia organizado tem antes, durante e depois.\n\nAntes do serviço:\n- confira equipe, escala e ausências;\n- veja reservas, eventos e previsão de movimento;\n- confira checklists, validades e controles;\n- faça uma reunião rápida com a equipe: o que tem hoje, o que acabou, o que vender.\n\nDurante:\n- fique onde o gargalo está;\n- olhe a qualidade antes de sair;\n- resolva problemas sem parar a operação.\n\nDepois:\n- confira fechamento, limpeza e perdas;\n- deixe o Memorando de amanhã pronto;\n- anote o que deu errado para resolver a causa.","questoes":[{"tipo":"prova","enunciado":"Onde o líder deve ficar no pico?","opcoes":["Onde está o gargalo","No escritório","No estoque"],"correta":0,"explicacao":"A maior ajuda é onde o serviço trava.","chave":"l-org-1-q1","ordem":1},{"tipo":"situacao","enunciado":"Dois funcionários faltaram e a casa tem reservas cheias.","opcoes":["Esperar o serviço para ver","Redistribuir funções, simplificar o que puder e avisar o gerente antes de abrir","Cancelar todas as reservas"],"correta":1,"explicacao":"Decida antes de abrir e ajuste a equipe.","chave":"l-org-1-q2","ordem":2}],"fontes":""},{"chave":"l-org-2","titulo":"Estoque, compras e perdas","duracao_minutos":7,"conteudo":"Quem lidera a área responde pelo que entra, sai e se perde.\n\n- Mantenha mínimos de estoque definidos no Héfisto.\n- Faça a contagem no dia combinado.\n- Veja o que está abaixo do mínimo antes de pedir.\n- Confira a compra quando chegar: quantidade, qualidade, validade e preço.\n- Registre as perdas com o motivo.\n- Veja o que vence primeiro e planeje o uso.\n\nCMV é o custo da mercadoria vendida. Em percentual, é o custo dividido pelo que foi vendido. Se o CMV sobe, procure a causa: porção maior, desperdício, preço de compra, furto ou erro de lançamento.\n\nNo Héfisto, esse número depende de faturamento lançado, ficha correta e estoque lançado. Número ruim na entrada dá decisão ruim na saída.","questoes":[{"tipo":"prova","enunciado":"Como se calcula o CMV em percentual?","opcoes":["Custo da mercadoria vendida dividido pelas vendas","Vendas menos salários","Preço de venda dividido pelo número de pratos"],"correta":0,"explicacao":"O resultado mostra quanto da venda virou custo de mercadoria.","chave":"l-org-2-q1","ordem":1},{"tipo":"situacao","enunciado":"O CMV subiu e ninguém sabe por quê.","opcoes":["Aumentar todos os preços","Conferir porções, perdas, compras e lançamentos","Ignorar até o próximo mês"],"correta":1,"explicacao":"Procure a causa antes de agir.","chave":"l-org-2-q2","ordem":2}],"fontes":""}]},{"chave":"l-ficha","area":"gestao","ordem":430,"titulo":"Elaboração de ficha técnica","descricao":"Como criar a ficha que forma a equipe e controla o custo.","tipo":"aulas","aulas":[{"chave":"l-fic-1","titulo":"O que uma boa ficha tem","duracao_minutos":7,"conteudo":"Uma ficha completa responde a tudo que alguém novo precisaria saber:\n\n- nome, categoria e área;\n- ingredientes com quantidade e unidade;\n- rendimento e tamanho da porção;\n- modo de preparo em passos numerados;\n- montagem, foto do prato pronto e guarnição;\n- no bar: copo, gelo, método e guarnição;\n- validade e como conservar;\n- alérgenos.\n\nAtenção: o treinamento da equipe puxa esses dados direto da ficha. Prato sem modo de preparo aparece como pendência. Ficha completa é o treinamento pronto.\n\nTeste a ficha: peça para outra pessoa fazer o prato só lendo. Onde ela travar, a ficha precisa melhorar.","questoes":[{"tipo":"prova","enunciado":"Como saber se a ficha está clara?","opcoes":["Outra pessoa consegue fazer o prato só lendo","Ela tem muitas páginas","Foi feita pelo chefe"],"correta":0,"explicacao":"A ficha precisa funcionar sem você por perto.","chave":"l-fic-1-q1","ordem":1},{"tipo":"prova","enunciado":"O que acontece com um prato sem modo de preparo no treinamento?","opcoes":["O sistema inventa os passos","Aparece como pendência","É apagado"],"correta":1,"explicacao":"O Héfisto não inventa receita.","chave":"l-fic-1-q2","ordem":2},{"tipo":"situacao","enunciado":"O novato pergunta como fazer um prato cuja ficha só tem ingredientes.","opcoes":["Mandar perguntar a um colega","Ensinar e completar a ficha com passos e foto","Mandar adivinhar"],"correta":1,"explicacao":"Ao escrever, você ensina todos os próximos.","chave":"l-fic-1-q3","ordem":3}],"fontes":""},{"chave":"l-fic-2","titulo":"Quantidade, perda e custo","duracao_minutos":7,"conteudo":"Dois pesos importam:\n\n- Peso bruto: como o ingrediente chega.\n- Peso líquido: o que sobra depois de limpar.\n\nFator de correção = peso bruto ÷ peso líquido.\n\nExemplo: 1 kg de peixe que rende 800 g depois de limpo tem fator 1,25. Para servir 800 g, você precisa comprar 1 kg.\n\nSem esse fator, o custo do prato fica menor do que o real.\n\nCusto da ficha: soma do custo de cada ingrediente, usando a quantidade certa. Custo da porção: custo total dividido pelo rendimento.\n\nCMV do prato: custo da porção dividido pelo preço de venda. Compare com a meta da casa.\n\nUse as unidades certas: gramas e quilos, mililitros e litros. Um erro de unidade muda o custo inteiro. Sempre confira o resultado: se um prato deu um custo estranho, olhe as unidades antes de tudo.","questoes":[{"tipo":"prova","enunciado":"1 kg de um produto rende 500 g limpo. Qual é o fator de correção?","opcoes":["0,5","1,5","2"],"correta":2,"explicacao":"1000 ÷ 500 = 2.","chave":"l-fic-2-q1","ordem":1},{"tipo":"prova","enunciado":"Uma ficha custa R$ 40 e rende 8 porções. Qual é o custo da porção?","opcoes":["R$ 5","R$ 8","R$ 32"],"correta":0,"explicacao":"R$ 40 ÷ 8 = R$ 5.","chave":"l-fic-2-q2","ordem":2},{"tipo":"prova","enunciado":"A porção custa R$ 10 e o prato é vendido a R$ 40. Qual é o CMV do prato?","opcoes":["10%","25%","40%"],"correta":1,"explicacao":"10 ÷ 40 = 25%.","chave":"l-fic-2-q3","ordem":3},{"tipo":"situacao","enunciado":"Uma ficha mostra um prato simples com custo de R$ 900.","opcoes":["Publicar assim","Conferir unidades e quantidades","Aumentar o preço de venda"],"correta":1,"explicacao":"Custo absurdo costuma ser erro de unidade, como gramas lançadas como quilos.","chave":"l-fic-2-q4","ordem":4}],"fontes":""},{"chave":"l-fic-3","titulo":"Criar e manter fichas no Héfisto","duracao_minutos":6,"conteudo":"Passos:\n1. Abra Fichas técnicas na sua área.\n2. Crie a ficha ou abra a existente.\n3. Lance os ingredientes do cadastro, com quantidade e unidade.\n4. Informe rendimento e porção.\n5. Escreva o preparo em passos curtos.\n6. Complete a montagem e coloque a foto.\n7. Faça o prato seguindo a ficha, ajuste e só então libere.\n\nRevise a ficha sempre que a receita, o fornecedor ou o preço mudar.\n\nQuando a receita muda, avise a equipe. O que muda na ficha aparece no treinamento, mas quem já foi validado precisa aprender a mudança.","questoes":[{"tipo":"prova","enunciado":"Quando revisar uma ficha?","opcoes":["Quando a receita, o fornecedor ou o preço mudar","Só uma vez por ano","Nunca"],"correta":0,"explicacao":"Ficha velha ensina errado e custa errado.","chave":"l-fic-3-q1","ordem":1}],"fontes":""}]},{"chave":"l-salao","area":"gestao","ordem":440,"titulo":"Comando do salão","descricao":"Para chefe de fila e maître.","tipo":"aulas","aulas":[{"chave":"l-sal-1","titulo":"Distribuir o salão","duracao_minutos":6,"conteudo":"Antes de abrir, defina setores e responsáveis com base nas reservas e na equipe.\n\n- Distribua as mesas para que nenhum setor fique pesado.\n- Controle a fila e informe tempos reais.\n- Reserve tempo para arrumar a mesa entre um cliente e outro.\n- Avise a cozinha sobre grupos grandes antes do pedido.\n- Circule pelo salão: veja copos vazios, pratos parados e clientes procurando alguém.\n\nFale com as mesas. Uma pergunta simples, \"como está tudo?\", descobre problemas antes da reclamação.","questoes":[{"tipo":"prova","enunciado":"O que fazer quando chega um grupo grande?","opcoes":["Avisar a cozinha antes do pedido","Esperar o pedido sair","Colocar o grupo no bar"],"correta":0,"explicacao":"A cozinha se prepara, e a saída não trava.","chave":"l-sal-1-q1","ordem":1},{"tipo":"situacao","enunciado":"A fila está longa e um cliente pergunta quanto vai demorar.","opcoes":["Dizer 5 minutos para acalmar","Dar o tempo real e oferecer algo do bar enquanto espera","Dizer que não sabe"],"correta":1,"explicacao":"Tempo falso gera a pior reclamação.","chave":"l-sal-1-q2","ordem":2}],"fontes":""},{"chave":"l-sal-2","titulo":"Recuperar um cliente","duracao_minutos":6,"conteudo":"Quando a equipe chama você, o cliente já está insatisfeito. Sua função é mudar o rumo.\n\n1. Vá até a mesa logo. Apresente-se.\n2. Ouça até o fim, sem justificar.\n3. Peça desculpas pelo que ele viveu.\n4. Pergunte o que seria justo ou proponha uma solução.\n5. Resolva dentro do que a casa permite.\n6. Volte à mesa antes de ele sair.\n7. Registre e trate a causa com a equipe.\n\n[PREENCHER: até quanto o líder pode dar de cortesia ou desconto sem falar com o dono.]","questoes":[{"tipo":"prova","enunciado":"Qual é o primeiro passo ao ser chamado para uma reclamação?","opcoes":["Justificar o erro","Ouvir até o fim","Oferecer desconto"],"correta":1,"explicacao":"Quem se sente ouvido já está mais calmo.","chave":"l-sal-2-q1","ordem":1},{"tipo":"situacao","enunciado":"Um cliente insatisfeito ameaça fazer uma avaliação ruim.","opcoes":["Responder que ele pode fazer","Ouvir, resolver o problema real e registrar o caso","Oferecer cortesia em troca de não avaliar"],"correta":1,"explicacao":"Resolva o problema. Não negocie avaliações.","chave":"l-sal-2-q2","ordem":2}],"fontes":""}]},{"chave":"l-gerente","area":"gestao","ordem":450,"titulo":"Gestão da casa","descricao":"Para o gerente: abertura, fechamento e crise.","tipo":"aulas","aulas":[{"chave":"l-ger-1","titulo":"Abrir e fechar a casa","duracao_minutos":6,"conteudo":"O gerente garante o conjunto.\n\nAbertura:\n- equipe completa e nos postos;\n- checklists de cada área;\n- estoque crítico e contas do dia;\n- reservas e eventos;\n- caixa e meios de pagamento funcionando.\n\nFechamento:\n- conferência do caixa;\n- faturamento lançado no Héfisto;\n- checklists de fechamento;\n- gás, energia, geladeiras, portas e alarmes;\n- recado para o turno seguinte.\n\nSem o faturamento lançado, os indicadores da casa ficam sem dado.\n\n[PREENCHER: como funciona o caixa da casa e quem pode fazer sangria.]","questoes":[{"tipo":"prova","enunciado":"O que precisa ser lançado todos os dias para os indicadores funcionarem?","opcoes":["O faturamento do dia","A música tocada","O nome dos clientes"],"correta":0,"explicacao":"Sem faturamento, não há CMV nem resultado do dia.","chave":"l-ger-1-q1","ordem":1},{"tipo":"situacao","enunciado":"O caixa fechou com diferença.","opcoes":["Ajustar o número para bater","Conferir, registrar a diferença e tratar a causa","Deixar para o mês seguinte"],"correta":1,"explicacao":"Diferença se registra. Nunca se esconde.","chave":"l-ger-1-q2","ordem":2}],"fontes":""},{"chave":"l-ger-2","titulo":"Quando dá tudo errado","duracao_minutos":6,"conteudo":"Em uma crise, o gerente é quem mantém a calma.\n\n1. Garanta primeiro a segurança das pessoas.\n2. Avalie e decida em poucos minutos.\n3. Fale com a equipe de forma clara.\n4. Diga a verdade aos clientes.\n5. Registre tudo e avise o dono.\n\nVigilância sanitária ou fiscal na casa: receba com educação, acompanhe, não esconda nada e avise o dono na hora.\n\nSuspeita de intoxicação alimentar: ouça o cliente, registre os dados, guarde o que puder ser guardado do alimento e avise o dono no mesmo dia.","questoes":[{"tipo":"prova","enunciado":"O que vem primeiro em uma crise?","opcoes":["A segurança das pessoas","A venda do dia","A avaliação na internet"],"correta":0,"explicacao":"Pessoas primeiro, sempre.","chave":"l-ger-2-q1","ordem":1},{"tipo":"situacao","enunciado":"Chega a vigilância sanitária no meio do serviço.","opcoes":["Esconder produtos","Receber com educação, acompanhar e avisar o don